# Tienda de repuestos Samsung (estática, pedidos por WhatsApp). Uso: python3 tienda_repuestos.py /ruta/salida
import ast, html, json, os, re, shutil, sys, unicodedata, urllib.parse, pathlib
AQUI = pathlib.Path(__file__).resolve().parent
OUT = pathlib.Path(sys.argv[1] if len(sys.argv) > 1 else "/tmp/tienda")
NOMBRE = os.environ.get("TIENDA_NOMBRE", "Repuestos Samsung Cali")
DOM = os.environ.get("TIENDA_DOMINIO", "https://repuestossamsungcali.com").rstrip("/")
WA = os.environ.get("TIENDA_WA", "573013810242"); WAV = "+57 301 381 0242"
DIR = os.environ.get("TIENDA_DIR", "Cl. 65, Las Ceibas, Cali, Valle del Cauca")
MAIL = os.environ.get("TIENDA_MAIL", "ventas@tudominio.com")
CIUDAD = "Cali"
esc = lambda s: html.escape(str(s), quote=True)
def slug(n):
    n = unicodedata.normalize("NFKD", str(n)).encode("ascii", "ignore").decode().lower()
    return re.sub(r"[^a-z0-9]+", "-", n).strip("-")
src = ast.parse((AQUI.parent / "st_extra11.py").read_text(encoding="utf-8"))
PIEZAS = next(ast.literal_eval(n.value) for n in ast.walk(src) if isinstance(n, ast.Assign) and any(getattr(x, "id", "") == "PIEZAS" for x in n.targets))
CATS = {"nevera": ("Neveras", "Repuestos para neveras Samsung", "❄", "#0e7490"), "lava": ("Lavadoras", "Repuestos para lavadoras Samsung", "◎", "#1d4ed8"),
        "seca": ("Secadoras", "Repuestos para secadoras Samsung", "☼", "#b45309"), "lavaplatos": ("Lavavajillas", "Repuestos para lavavajillas Samsung", "✦", "#0f766e"),
        "cocina": ("Estufas y hornos", "Repuestos para estufas y hornos Samsung", "♨", "#b91c1c"), "micro": ("Microondas", "Repuestos para microondas Samsung", "≋", "#6d28d9")}
CAT_SLUG = {k: slug(v[0]) for k, v in CATS.items()}
PROD = []
for k, lst in PIEZAS.items():
    for key, nom, desc, sen in lst:
        PROD.append(dict(cat=k, nombre=nom, desc=desc, sen=sen, slug=f"{slug(nom)}-{CAT_SLUG[k]}-samsung", titulo=f"{nom} para {CATS[k][0].lower().rstrip('s') if k not in ('cocina','lavaplatos') else CATS[k][0].lower()} Samsung"))
def p_url(p): return f"repuesto/{p['slug']}/"
def c_url(k): return f"categoria/{CAT_SLUG[k]}/"
def wa(msg): return f"https://wa.me/{WA}?text=" + urllib.parse.quote(msg)
