            f'<div class="bd"><span class="ca">{n} Samsung</span><h3><a href="@@R@@{p_url(p)}">{esc(p["titulo"])}</a></h3><p>{esc(p["desc"][:92].rsplit(" ",1)[0])}…</p><span class="pr">Cotiza por tu modelo</span>'
