(OUT / "tienda.js").write_text(JS, encoding="utf-8")
shutil.copytree(AQUI / "img", OUT / "img")
for _f in ("logo-mark.svg", "favicon.png", "logo-512.png", "og.jpg"): shutil.copy(AQUI / _f, OUT / _f)
urls = []
for path, (t, prio) in PAGES.items():
    d = OUT / path; d.mkdir(parents=True, exist_ok=True); (d / "index.html").write_text(t, encoding="utf-8")
    if path != "cotizacion/": urls.append((path, prio))
(OUT / "404.html").write_text(head("Página no encontrada", "No encontramos la página.", "404.html").replace("@@R@@", "/") + header().replace("@@R@@", "/") + '<section class="s"><div class="wrap"><h1>Página no encontrada</h1><p><a href="/">Volver al inicio</a> · <a href="/tienda/">Ver la tienda</a></p></div></section>' + footer().replace("@@R@@", "/"), encoding="utf-8")
(OUT / "sitemap.xml").write_text('<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">' + "".join(f"<url><loc>{DOM}/{u}</loc><priority>{p}</priority></url>" for u, p in urls) + "</urlset>", encoding="utf-8")
(OUT / "robots.txt").write_text(f"User-agent: *\nAllow: /\nDisallow: /cotizacion/\nSitemap: {DOM}/sitemap.xml\n", encoding="utf-8")
(OUT / "llms.txt").write_text(f"# {NOMBRE}\n> Tienda independiente de repuestos para línea blanca Samsung en {CIUDAD}, Colombia. Cotización por modelo vía WhatsApp {WAV}. Dirección: {DIR}.\n\n" + "\n".join(f"- [{p['titulo']}]({DOM}/{p_url(p)})" for p in PROD) + "\n", encoding="utf-8")
(OUT / ".htaccess").write_text("ErrorDocument 404 /404.html\nDirectoryIndex index.html\n<IfModule mod_expires.c>\nExpiresActive On\nExpiresByType text/css \"access plus 1 week\"\nExpiresByType application/javascript \"access plus 1 week\"\n</IfModule>\n", encoding="utf-8")
print("listo", OUT, len(PAGES), "páginas;", len(PROD), "repuestos")
